    "<strong>Android (Chrome):</strong> tap ⋮ menu → <em>Add to Home screen</em> or <em>Install app</em>.": "<strong>Android (Chrome):</strong> ⋮ ਮੀਨੂ 'ਤੇ ਟੈਪ ਕਰੋ → <em>Add to Home screen</em> ਜਾਂ <em>Install app</em>।",
