    "Back up progress": "ਤਰੱਕੀ ਦਾ ਬੈਕਅੱਪ",
    "Progress is saved only on this phone. Save a backup file before deleting the app or moving to a new phone, then restore it there.": "ਤਰੱਕੀ ਸਿਰਫ਼ ਇਸ ਫ਼ੋਨ 'ਤੇ ਸੰਭਾਲੀ ਜਾਂਦੀ ਹੈ। ਐਪ ਮਿਟਾਉਣ ਜਾਂ ਨਵੇਂ ਫ਼ੋਨ 'ਤੇ ਜਾਣ ਤੋਂ ਪਹਿਲਾਂ ਬੈਕਅੱਪ ਫ਼ਾਈਲ ਸੰਭਾਲੋ, ਫਿਰ ਉੱਥੇ ਰੀਸਟੋਰ ਕਰੋ।",
    "Progress is saved only in this browser. Save a backup file before clearing browser data or moving to a new phone, then restore it there.": "ਤਰੱਕੀ ਸਿਰਫ਼ ਇਸ ਬ੍ਰਾਊਜ਼ਰ ਵਿੱਚ ਸੰਭਾਲੀ ਜਾਂਦੀ ਹੈ। ਬ੍ਰਾਊਜ਼ਰ ਦਾ ਡਾਟਾ ਮਿਟਾਉਣ ਜਾਂ ਨਵੇਂ ਫ਼ੋਨ 'ਤੇ ਜਾਣ ਤੋਂ ਪਹਿਲਾਂ ਬੈਕਅੱਪ ਫ਼ਾਈਲ ਸੰਭਾਲ ਲਓ, ਫਿਰ ਉੱਥੇ ਰੀਸਟੋਰ ਕਰੋ।",
    "Save backup": "ਬੈਕਅੱਪ ਸੰਭਾਲੋ",
    "Restore backup": "ਬੈਕਅੱਪ ਰੀਸਟੋਰ ਕਰੋ",
    "Save every class for offline": "ਹਰ ਜਮਾਤ ਆਫ਼ਲਾਈਨ ਲਈ ਸੰਭਾਲੋ",
    "Your own class is saved automatically. Use this if brothers or sisters share this phone (about 17 MB).": "ਤੁਹਾਡੀ ਆਪਣੀ ਜਮਾਤ ਆਪਣੇ-ਆਪ ਸੰਭਲ ਜਾਂਦੀ ਹੈ। ਜੇ ਭੈਣ-ਭਰਾ ਇਹ ਫ਼ੋਨ ਸਾਂਝਾ ਵਰਤਦੇ ਹਨ ਤਾਂ ਇਹ ਵਰਤੋ (ਲਗਭਗ 17 MB)।",
    "Save all": "ਸਭ ਸੰਭਾਲੋ",
    "Reset progress": "ਤਰੱਕੀ ਰੀਸੈੱਟ ਕਰੋ",
    "Clears this student's scores, streaks, bookmarks and mistakes.": "ਇਸ ਵਿਦਿਆਰਥੀ ਦੇ ਸਕੋਰ, ਸਟ੍ਰੀਕ, ਬੁੱਕਮਾਰਕ ਅਤੇ ਗ਼ਲਤੀਆਂ ਮਿਟਾ ਦਿੰਦਾ ਹੈ।",
    "About Pocket Class India": "Pocket Class India ਬਾਰੇ",
    "Notes, quizzes and tests are written for the CBSE / NCERT and PSEB syllabi, Classes 1 to 12. Each subject page says whether it follows the current NCERT book, an older one, or is arranged by topic. Punjabi covers grammar and writing skills for CBSE and PSEB students. The content has not yet been checked by teachers, so use it for revision alongside your textbook, and check with your teacher if anything looks different from your book. Your progress is stored only on this device.": "ਨੋਟਸ, ਕੁਇਜ਼ ਅਤੇ ਟੈਸਟ ਜਮਾਤ 1 ਤੋਂ 12 ਲਈ CBSE / NCERT ਅਤੇ PSEB ਦੇ ਸਿਲੇਬਸ ਅਨੁਸਾਰ ਲਿਖੇ ਗਏ ਹਨ। ਹਰ ਵਿਸ਼ੇ ਦਾ ਪੰਨਾ ਦੱਸਦਾ ਹੈ ਕਿ ਇਹ ਮੌਜੂਦਾ NCERT ਕਿਤਾਬ ਅਨੁਸਾਰ ਹੈ, ਪੁਰਾਣੀ ਕਿਤਾਬ ਅਨੁਸਾਰ ਹੈ ਜਾਂ ਵਿਸ਼ਿਆਂ ਅਨੁਸਾਰ ਵੰਡਿਆ ਗਿਆ ਹੈ। ਪੰਜਾਬੀ ਵਿੱਚ CBSE ਅਤੇ PSEB ਦੇ ਵਿਦਿਆਰਥੀਆਂ ਲਈ ਵਿਆਕਰਨ ਅਤੇ ਲਿਖਣ ਦੇ ਹੁਨਰ ਸ਼ਾਮਲ ਹਨ। ਸਮੱਗਰੀ ਹਾਲੇ ਅਧਿਆਪਕਾਂ ਵੱਲੋਂ ਜਾਂਚੀ ਨਹੀਂ ਗਈ, ਇਸ ਲਈ ਇਸਨੂੰ ਆਪਣੀ ਕਿਤਾਬ ਦੇ ਨਾਲ ਦੁਹਰਾਈ ਲਈ ਵਰਤੋ, ਅਤੇ ਜੇ ਕੁਝ ਕਿਤਾਬ ਨਾਲੋਂ ਵੱਖਰਾ ਲੱਗੇ ਤਾਂ ਆਪਣੇ ਅਧਿਆਪਕ ਤੋਂ ਪੁੱਛੋ। ਤੁਹਾਡੀ ਤਰੱਕੀ ਸਿਰਫ਼ ਇਸ ਡਿਵਾਈਸ 'ਤੇ ਸੰਭਾਲੀ ਜਾਂਦੀ ਹੈ।",
