    "Brothers and sisters can share this device. Each student has their own progress, mistakes and streak.": "ਭੈਣ-ਭਰਾ ਇੱਕੋ ਡਿਵਾਈਸ ਵਰਤ ਸਕਦੇ ਹਨ। ਹਰ ਵਿਦਿਆਰਥੀ ਦੀ ਆਪਣੀ ਤਰੱਕੀ, ਗ਼ਲਤੀਆਂ ਅਤੇ ਲਗਾਤਾਰ ਦਿਨਾਂ ਦੀ ਲੜੀ ਹੁੰਦੀ ਹੈ।",
