    "Lowest quiz accuracy, from chapters with at least 5 questions answered.": "ਕੁਇਜ਼ ਵਿੱਚ ਸਭ ਤੋਂ ਘੱਟ ਸਹੀ ਜਵਾਬ, ਉਨ੍ਹਾਂ ਅਧਿਆਵਾਂ ਵਿੱਚੋਂ ਜਿਨ੍ਹਾਂ ਦੇ ਘੱਟੋ-ਘੱਟ 5 ਸਵਾਲ ਹੱਲ ਕੀਤੇ ਗਏ।",
    "{n}% right of {a} answers": "{a} ਜਵਾਬਾਂ ਵਿੱਚੋਂ {n}% ਸਹੀ",
    "Answer quiz questions in a few chapters to see which ones need more practice.": "ਕੁਝ ਅਧਿਆਵਾਂ ਦੇ ਕੁਇਜ਼ ਹੱਲ ਕਰੋ, ਤਾਂ ਪਤਾ ਲੱਗੇਗਾ ਕਿਹੜਿਆਂ ਨੂੰ ਹੋਰ ਅਭਿਆਸ ਚਾਹੀਦਾ ਹੈ।",
    "Open mistakes": "ਬਾਕੀ ਗ਼ਲਤੀਆਂ",
