    "Current in R₁ / R₂": "R₁ / R₂ ਵਿੱਚ ਧਾਰਾ",
    "Same voltage across both": "ਦੋਵਾਂ ਉੱਤੇ ਇੱਕੋ ਵੋਲਟੇਜ",
