    "<strong>Android (Chrome):</strong> tap ⋮ menu → <em>Add to Home screen</em> or <em>Install app</em>.": "<strong>Android (Chrome):</strong> ⋮ मेन्यू पर टैप करें → <em>Add to Home screen</em> या <em>Install app</em>।",
    "<strong>iPhone (Safari):</strong> tap Share → <em>Add to Home Screen</em>.": "<strong>iPhone (Safari):</strong> Share पर टैप करें → <em>Add to Home Screen</em>।",
