    "Back up progress": "प्रगति का बैकअप",
    "Progress is saved only on this phone. Save a backup file before deleting the app or moving to a new phone, then restore it there.": "प्रगति केवल इस फ़ोन पर सहेजी जाती है। ऐप हटाने या नए फ़ोन पर जाने से पहले बैकअप फ़ाइल सहेजें, फिर वहाँ रिस्टोर करें।",
    "Progress is saved only in this browser. Save a backup file before clearing browser data or moving to a new phone, then restore it there.": "प्रगति सिर्फ़ इस ब्राउज़र में सहेजी जाती है। ब्राउज़र का डेटा मिटाने या नए फ़ोन पर जाने से पहले बैकअप फ़ाइल सहेज लें, फिर वहाँ रीस्टोर करें।",
    "Save backup": "बैकअप सहेजें",
    "Restore backup": "बैकअप रीस्टोर करें",
    "Save every class for offline": "हर कक्षा ऑफ़लाइन के लिए सहेजें",
    "Your own class is saved automatically. Use this if brothers or sisters share this phone (about 17 MB).": "आपकी अपनी कक्षा अपने आप सहेज ली जाती है। अगर भाई-बहन यह फ़ोन साझा करते हैं तो इसका उपयोग करें (लगभग 17 MB)।",
    "Save all": "सभी सहेजें",
    "Reset progress": "प्रगति रीसेट करें",
    "Clears this student's scores, streaks, bookmarks and mistakes.": "इस विद्यार्थी के स्कोर, स्ट्रीक, बुकमार्क और गलतियाँ मिटा देता है।",
    "About Pocket Class India": "Pocket Class India के बारे में",
    "Notes, quizzes and tests are written for the CBSE / NCERT and PSEB syllabi, Classes 1 to 12. Each subject page says whether it follows the current NCERT book, an older one, or is arranged by topic. Punjabi covers grammar and writing skills for CBSE and PSEB students. The content has not yet been checked by teachers, so use it for revision alongside your textbook, and check with your teacher if anything looks different from your book. Your progress is stored only on this device.": "नोट्स, क्विज़ और टेस्ट कक्षा 1 से 12 के लिए CBSE / NCERT और PSEB के सिलेबस के अनुसार लिखे गए हैं। हर विषय का पेज बताता है कि वह मौजूदा NCERT किताब के अनुसार है, पुरानी किताब के अनुसार है, या विषयों के अनुसार बाँटा गया है। पंजाबी में CBSE और PSEB के विद्यार्थियों के लिए व्याकरण और लेखन कौशल शामिल हैं। सामग्री अभी शिक्षकों द्वारा जाँची नहीं गई है, इसलिए इसे अपनी किताब के साथ दोहराव के लिए इस्तेमाल करें, और अगर कुछ किताब से अलग लगे तो अपने शिक्षक से पूछें। आपकी प्रगति सिर्फ़ इसी डिवाइस पर सहेजी जाती है।",
    "Replace the progress on this device with this backup?": "इस डिवाइस की प्रगति को इस बैकअप से बदलना है?",
    "That file isn't a Pocket Class backup": "यह फ़ाइल Pocket Class का बैकअप नहीं है",
    "Progress restored": "प्रगति बहाल हो गई",
