    "Tip: Space flips, ← still learning, → I know this.": "सुझाव: स्पेस से कार्ड पलटें, ← अभी सीखना है, → मुझे आता है।",
    "Step {i} of {n}": "{n} में से चरण {i}",
    "Before the lesson, have a go at this. A guess is fine: it is not counted anywhere.": "पाठ से पहले इसे एक बार आज़माएँ। अंदाज़ा भी चलेगा: यह कहीं गिना नहीं जाता।",
