    "Your first guess was right 🎉": "आपका पहला अंदाज़ा सही था 🎉",
    "Here is the answer": "यह रहा उत्तर",
    "Not that one, and now you can see why": "यह नहीं, और अब आप देख सकते हैं कि क्यों",
    "The question you saw at the start, with what you now know.": "शुरू में देखा प्रश्न, अब जो आपने सीखा उसके साथ।",
    "This chapter has no solved example yet, so let's go straight to a question.": "इस अध्याय में अभी कोई हल किया उदाहरण नहीं है, इसलिए सीधे एक प्रश्न की ओर चलते हैं।",
    "Read each step and ask yourself <strong>why</strong> it works before moving to the next.": "हर चरण पढ़ें और अगले पर जाने से पहले खुद से पूछें कि यह <strong>क्यों</strong> काम करता है।",
    "No similar question is available for this chapter yet.": "इस अध्याय के लिए अभी कोई मिलता-जुलता प्रश्न उपलब्ध नहीं है।",
    "Step {n}": "चरण {n}",
    "Here is the full solution": "यह रहा पूरा हल",
    "You used {n} {n:hint|hints}.": "आपने {n} संकेत इस्तेमाल किए।",
    "No hints needed.": "किसी संकेत की ज़रूरत नहीं पड़ी।",
    "Compare the steps with the worked example.": "चरणों को हल किए उदाहरण से मिलाकर देखें।",
    "Show a hint": "संकेत देखें",
    "({n} left)": "({n} बाकी)",
    "Show the solution": "हल देखें",
    "Same idea, new numbers. Try it in your head or notebook first. Hints reveal the steps one at a time.": "वही विचार, नई संख्याएँ। पहले मन में या कॉपी पर करके देखें। संकेत एक-एक करके चरण दिखाते हैं।",
    "No practice questions for this chapter yet.": "इस अध्याय के लिए अभी कोई अभ्यास प्रश्न नहीं हैं।",
    "How sure are you?": "आपको कितना यकीन है?",
    "Sure": "पक्का",
    "Not sure": "पक्का नहीं",
    "Correct, and you knew it 🎉": "सही, और आपको पता था 🎉",
    "Correct! Here's why, so it sticks": "सही! यह रहा कारण, ताकि याद रहे",
    "Not this time. You were sure, so read this carefully": "इस बार नहीं। आपको पक्का था, इसलिए इसे ध्यान से पढ़ें",
    "Not quite, and you sensed it": "सही नहीं, और आपको यह महसूस हो गया था",
    "Read the notes again": "नोट्स दोबारा पढ़ें",
    "Three questions, easy to hard. After each answer, say how sure you were.": "तीन प्रश्न, आसान से कठिन। हर उत्तर के बाद बताएँ कि आपको कितना यकीन था।",
    "This is the last chapter of {subject} for Class {n}. Well done for getting here.": "यह कक्षा {n} के {subject} का आखिरी अध्याय है। यहाँ तक पहुँचने के लिए शाबाश।",
    "The next chapter is <strong>{title}</strong>. Here is a taste of it. Think about it; the answer is there when you want it.": "अगला अध्याय <strong>{title}</strong> है। यह उसकी एक झलक है। इसके बारे में सोचें; जब चाहें उत्तर वहीं है।",
    "Show the answer": "उत्तर देखें",
    "Your first guess, before the lesson, was already right.": "पाठ से पहले आपका पहला अंदाज़ा पहले ही सही था।",
    "Your first guess was off, and the lesson sorted it out.": "आपका पहला अंदाज़ा गलत था, और पाठ ने बात साफ़ कर दी।",
    "{n} {n:answer|answers} where you were sure but wrong: those are the ideas to re-read.": "{n} उत्तर जहाँ आपको पक्का था पर गलत निकले: ये वे विचार हैं जिन्हें दोबारा पढ़ना है।",
    "{n} answers right but unsure: a few more questions will make them stick.": "{n} उत्तर सही पर पक्का नहीं था: कुछ और प्रश्न इन्हें पक्का कर देंगे।",
    "1 answer right but unsure: a few more questions will make it stick.": "1 उत्तर सही पर पक्का नहीं था: कुछ और प्रश्न इसे पक्का कर देंगे।",
    "Every practice question right and sure. Try the full quiz next.": "अभ्यास का हर प्रश्न सही और पक्के यकीन के साथ। अब पूरा क्विज़ आज़माएँ।",
    "practice": "अभ्यास",
    "Lesson complete": "पाठ पूरा हुआ",
    "Practise my mistakes": "मेरी गलतियों का अभ्यास करें",
    "Take the chapter quiz": "अध्याय का क्विज़ दें",
    "Next chapter": "अगला अध्याय",
    "Back to notes": "नोट्स पर वापस",
    "Do it again": "दोबारा करें",
    "Done {when} · {score}/{total} in practice. Do it again for a different set of questions.": "{when} पूरा किया · अभ्यास में {score}/{total}। प्रश्नों के नए सेट के लिए दोबारा करें।",
    "Learn this chapter step by step: a question first, then the idea, a worked example, practice and a confidence check. About 10 minutes.": "इस अध्याय को चरण-दर-चरण सीखें: पहले एक प्रश्न, फिर विचार, एक हल किया उदाहरण, अभ्यास और यकीन की जाँच। लगभग 10 मिनट।",
    "New": "नया",
    "Choose chapters and question types. Every sheet has an answer key, and there's always a new sheet with different questions.": "अध्याय और प्रश्नों के प्रकार चुनें। हर शीट में उत्तर कुंजी होती है, और नए प्रश्नों वाली नई शीट हमेशा मिल जाती है।",
    "unlimited, new numbers every sheet": "असीमित, हर शीट में नई संख्याएँ",
    "{n} available": "{n} उपलब्ध",
