    "A notification each day at the time you choose, to remind you to practise. It works without internet and nothing leaves your phone.": "आपके चुने समय पर हर दिन एक नोटिफ़िकेशन, अभ्यास की याद दिलाने के लिए। यह इंटरनेट के बिना चलता है और कुछ भी आपके फ़ोन से बाहर नहीं जाता।",
