    "Reminder time": "रिमाइंडर का समय",
    "Reminder set for {time}": "रिमाइंडर {time} के लिए लगा दिया गया",
    "Reminder turned off": "रिमाइंडर बंद कर दिया गया",
    "Notifications are turned off for this app. Allow them in your phone's settings to use reminders.": "इस ऐप के लिए नोटिफ़िकेशन बंद हैं। रिमाइंडर इस्तेमाल करने के लिए फ़ोन की सेटिंग्स में इन्हें चालू करें।",
    "5 minutes of practice? Your question of the day is waiting.": "5 मिनट अभ्यास करेंगे? आज का सवाल आपका इंतज़ार कर रहा है।",
    // learning methods: fading, find the mistake, teach-back, experiments
    "Image formation: lens and mirror": "प्रतिबिंब बनना: लेंस और दर्पण",
    "A convex lens has focal length 10 cm and the object is 30 cm away. You slide the object to 15 cm. What happens to the image?": "एक उत्तल लेंस की फ़ोकस दूरी 10 cm है और वस्तु 30 cm दूर है। आप वस्तु को 15 cm पर ले आते हैं। प्रतिबिंब का क्या होगा?",
    "It gets smaller and moves closer to the lens": "यह छोटा हो जाएगा और लेंस के पास आ जाएगा",
    "It gets bigger and moves farther from the lens": "यह बड़ा हो जाएगा और लेंस से दूर चला जाएगा",
    "It becomes virtual and upright": "यह आभासी और सीधा हो जाएगा",
    "Set the object distance to 15 cm and compare the image with the one at 30 cm. Then keep going below 10 cm.": "वस्तु की दूरी 15 cm करें और प्रतिबिंब की 30 cm वाले से तुलना करें। फिर 10 cm से कम तक जाएँ।",
    "At 15 cm, 1/v = 1/10 − 1/15, so v = 30 cm and m = −2: a real, inverted image twice as large, farther from the lens. The image only becomes virtual and upright when the object is closer than the focal length (here, under 10 cm).": "15 cm पर 1/v = 1/10 − 1/15, इसलिए v = 30 cm और m = −2: वास्तविक, उल्टा, दोगुना बड़ा प्रतिबिंब, लेंस से और दूर। प्रतिबिंब तभी आभासी और सीधा बनता है जब वस्तु फ़ोकस दूरी से पास हो (यहाँ 10 cm से कम)।",
    "Device": "उपकरण",
    "Convex lens": "उत्तल लेंस",
    "Concave mirror": "अवतल दर्पण",
    "Focal length": "फ़ोकस दूरी",
    "Object distance": "वस्तु की दूरी",
    "Ohm's law: current, voltage and resistance": "ओम का नियम: धारा, वोल्टेज और प्रतिरोध",
    "A 6 V cell is joined to a 10 Ω resistor, so the current is 0.6 A. You change the resistor to 20 Ω. The current will…": "6 V का सेल 10 Ω के प्रतिरोधक से जुड़ा है, इसलिए धारा 0.6 A है। आप प्रतिरोधक को 20 Ω का कर देते हैं। धारा…",
    "double to 1.2 A": "दोगुनी होकर 1.2 A हो जाएगी",
    "halve to 0.3 A": "आधी होकर 0.3 A रह जाएगी",
    "stay at 0.6 A": "0.6 A ही रहेगी",
    "Set R₁ to 20 Ω and read the current. Then switch to series or parallel and add the second resistor.": "R₁ को 20 Ω करें और धारा पढ़ें। फिर श्रेणी या समानांतर चुनें और दूसरा प्रतिरोधक जोड़ें।",
    "I = V/R. With the same voltage, doubling R halves I: 6 ÷ 20 = 0.3 A. In series the resistances add (the current falls); in parallel each branch takes its own current V/R and they add (the current rises).": "I = V/R। वोल्टेज वही रहे तो R दोगुना करने से I आधी हो जाती है: 6 ÷ 20 = 0.3 A। श्रेणी में प्रतिरोध जुड़ते हैं (धारा घटती है); समानांतर में हर शाखा अपनी धारा V/R लेती है और वे जुड़ती हैं (धारा बढ़ती है)।",
    "Circuit": "परिपथ",
    "One resistor": "एक प्रतिरोधक",
    "Two in series": "दो श्रेणी में",
    "Two in parallel": "दो समानांतर में",
    "Voltage V": "वोल्टेज V",
    "Resistor R₁": "प्रतिरोधक R₁",
    "Resistor R₂": "प्रतिरोधक R₂",
    "Simple pendulum": "सरल लोलक",
    "A pendulum 0.25 m long swings with a period of about 1 s. You make it 4 times as long (1.00 m). The period will…": "0.25 m लंबा लोलक लगभग 1 s के आवर्तकाल से झूलता है। आप इसे 4 गुना लंबा (1.00 m) कर देते हैं। आवर्तकाल…",
    "become 4 s": "4 s हो जाएगा",
    "become about 2 s": "लगभग 2 s हो जाएगा",
    "stay at 1 s": "1 s ही रहेगा",
    "Set the length to 1.00 m and read the period. Then try the Moon's gravity.": "लंबाई 1.00 m करें और आवर्तकाल पढ़ें। फिर चंद्रमा का गुरुत्व त्वरण आज़माएँ।",
    "T = 2π√(L/g). T depends on the square root of L, so 4 times the length gives 2 times the period: T = 2π√(1.00/9.8) ≈ 2.01 s. The mass of the bob does not appear in the formula. A weaker g (the Moon) makes the pendulum slower.": "T = 2π√(L/g)। T, L के वर्गमूल पर निर्भर है, इसलिए 4 गुना लंबाई से आवर्तकाल 2 गुना होता है: T = 2π√(1.00/9.8) ≈ 2.01 s। गोलक का द्रव्यमान सूत्र में नहीं आता। कम g (चंद्रमा) लोलक को धीमा कर देता है।",
    "Gravity": "गुरुत्व",
    "Earth (9.8 m/s²)": "पृथ्वी (9.8 m/s²)",
    "Moon (1.6 m/s²)": "चंद्रमा (1.6 m/s²)",
    "Jupiter (24.8 m/s²)": "बृहस्पति (24.8 m/s²)",
    "Length L": "लंबाई L",
    "Starting angle": "आरंभिक कोण",
    "Start / pause": "शुरू / रोकें",
