    "Projectile motion": "प्रक्षेप्य गति",
    "A ball is thrown at 20 m/s. Which launch angle gives the longest range on level ground?": "एक गेंद 20 m/s की चाल से फेंकी जाती है। समतल ज़मीन पर सबसे लंबी परास किस कोण से मिलेगी?",
    "Try 30°, 45° and 60° and compare the range. The dashed path shows the complementary angle (90° − θ).": "30°, 45° और 60° आज़माएँ और परास की तुलना करें। बिंदीदार रेखा पूरक कोण (90° − θ) का पथ दिखाती है।",
    "R = v² sin 2θ / g is largest when sin 2θ = 1, that is θ = 45°: R = 400/9.8 ≈ 40.8 m. 30° and 60° give the same shorter range (35.3 m) because sin 60° = sin 120°. A steeper throw goes higher but lands sooner.": "R = v² sin 2θ / g सबसे अधिक तब होती है जब sin 2θ = 1, यानी θ = 45°: R = 400/9.8 ≈ 40.8 m। 30° और 60° दोनों वही छोटी परास (35.3 m) देते हैं क्योंकि sin 60° = sin 120°। ज़्यादा खड़ा फेंकने पर गेंद ऊँची जाती है पर जल्दी गिरती है।",
