    "Light goes from glass (n = 1.5) into air (n = 1.0), starting at 20° to the normal. As you increase the angle of incidence, what happens?": "प्रकाश काँच (n = 1.5) से हवा (n = 1.0) में जाता है, अभिलंब से 20° पर शुरू करके। आपतन कोण बढ़ाने पर क्या होता है?",
    "The ray bends towards the normal and always gets through": "किरण अभिलंब की ओर मुड़ती है और हमेशा बाहर निकल जाती है",
    "The ray bends away from the normal; beyond about 42° no light gets out": "किरण अभिलंब से दूर मुड़ती है; लगभग 42° के बाद कोई प्रकाश बाहर नहीं निकलता",
    "The ray goes straight on at every angle": "किरण हर कोण पर सीधी निकल जाती है",
    "Raise the angle of incidence slowly from 20° to 60° and watch the refracted ray.": "आपतन कोण को धीरे-धीरे 20° से 60° तक बढ़ाएँ और अपवर्तित किरण देखें।",
    "Going from a denser to a rarer medium, light bends away from the normal: sin r = 1.5 × sin i. At the critical angle sin c = 1/1.5, so c ≈ 41.8°, the refracted ray runs along the surface. Beyond it there is no refracted ray: all the light is reflected (total internal reflection).": "सघन माध्यम से विरल माध्यम में जाते समय प्रकाश अभिलंब से दूर मुड़ता है: sin r = 1.5 × sin i। क्रांतिक कोण पर sin c = 1/1.5, यानी c ≈ 41.8°, अपवर्तित किरण सतह के साथ-साथ चलती है। इससे अधिक पर कोई अपवर्तित किरण नहीं बचती: सारा प्रकाश परावर्तित हो जाता है (पूर्ण आंतरिक परावर्तन)।",
