    "The graph of y = x² − 2x − 3 crosses the x-axis at two points. You raise c from −3 to 3, which lifts the whole graph by 6. How many real roots are there now?": "y = x² − 2x − 3 का ग्राफ़ x-अक्ष को दो बिंदुओं पर काटता है। आप c को −3 से 3 करते हैं, जिससे पूरा ग्राफ़ 6 ऊपर उठ जाता है। अब कितने वास्तविक मूल हैं?",
    "Two": "दो",
    "One": "एक",
    "None": "कोई नहीं",
    "Set c to 3 and watch the vertex and the discriminant. Then find the c at which the curve only touches the axis.": "c को 3 करें और शीर्ष और विविक्तकर देखें। फिर वह c ढूँढ़ें जिस पर वक्र अक्ष को केवल छूता है।",
    "The lowest point (vertex) was at y = −4. After lifting by 6 it is at y = 2, above the x-axis, so the curve never reaches y = 0. The discriminant b² − 4ac = 4 − 12 = −8 is negative: no real roots. The graph just touches the axis when the discriminant is 0, here at c = 1.": "सबसे निचला बिंदु (शीर्ष) y = −4 पर था। 6 ऊपर उठने पर यह y = 2 पर है, x-अक्ष के ऊपर, इसलिए वक्र कभी y = 0 तक नहीं पहुँचता। विविक्तकर b² − 4ac = 4 − 12 = −8 ऋणात्मक है: कोई वास्तविक मूल नहीं। ग्राफ़ अक्ष को केवल तब छूता है जब विविक्तकर 0 हो, यहाँ c = 1 पर।",
